// The only place the offline service worker (/sw.js, generated by vite-plugin-pwa) is registered.
// It must never run in dev, inside an iframe, or on a Lovable preview: a worker there would keep
// serving old pages to the editor. Add ?sw=off to any address to remove it from that browser.

export const SW_PATH = "/sw.js";

/** Every screen, fetched once after the worker starts so each opens offline even if never visited. */
export const OFFLINE_PAGES = [
  "/",
  "/vender",
  "/produtos",
  "/dividas",
  "/clientes",
  "/relatorios",
  "/definicoes",
  "/mais",
  "/entrar",
] as const;

/** The worker caches same-origin requests carrying this header the same way it caches page loads. */
export const WARM_HEADER = "x-kitanda-offline";

const PROJECT_ID = "345497cb-c59d-477e-97c2-d60b7f12a733";
const PREVIEW_LABEL = /^(?:id-preview|preview)(?:-[a-z0-9]+)?--.+$/;
const LOVABLE_SUFFIXES = [".lovable.app", ".gpt-eng.com", ".gptengineer.run"];
const EDITOR_DOMAINS = ["lovableproject.com", "lovableproject-dev.com", "beta.lovable.dev"];

export function isPreviewHost(hostname: string): boolean {
  const host = hostname.toLowerCase();
  const label = host.split(".")[0] ?? "";
  if (LOVABLE_SUFFIXES.some((s) => host.endsWith(s))) {
    if (PREVIEW_LABEL.test(label)) return true;
    if (label === `project--${PROJECT_ID}-dev`) return true;
  }
  return EDITOR_DOMAINS.some((d) => host === d || host.endsWith(`.${d}`));
}

export function canUseOffline(where: { prod: boolean; inIframe: boolean; hostname: string; search: string }): boolean {
  if (!where.prod || where.inIframe) return false;
  if (new URLSearchParams(where.search).get("sw") === "off") return false;
  return !isPreviewHost(where.hostname);
}

async function removeAppWorkers() {
  const registrations = await navigator.serviceWorker.getRegistrations();
  await Promise.all(
    registrations
      .filter((r) => [r.active, r.waiting, r.installing].some((w) => w?.scriptURL.endsWith(SW_PATH)))
      .map((r) => r.unregister()),
  );
}

function inIframe() {
  try {
    return window.self !== window.top;
  } catch {
    return true;
  }
}

let started = false;

export async function startOfflineSupport() {
  if (started || typeof window === "undefined" || !("serviceWorker" in navigator)) return;
  started = true;
  const allowed = canUseOffline({
    prod: import.meta.env.PROD,
    inIframe: inIframe(),
    hostname: window.location.hostname,
    search: window.location.search,
  });
  try {
    if (!allowed) {
      await removeAppWorkers();
      return;
    }
    const { registerSW } = await import("virtual:pwa-register");
    registerSW({ immediate: true });
    await navigator.serviceWorker.ready;
    // On the very first visit the worker takes over a moment after it activates; requests sent
    // before that skip it and would not be saved for offline use.
    if (!navigator.serviceWorker.controller) {
      await new Promise<void>((resolve) => {
        navigator.serviceWorker.addEventListener("controllerchange", () => resolve(), { once: true });
        setTimeout(resolve, 10_000);
      });
    }
    if (!navigator.onLine || !navigator.serviceWorker.controller) return;
    await Promise.allSettled(
      OFFLINE_PAGES.map((page) =>
        fetch(page, { headers: { [WARM_HEADER]: "1", accept: "text/html" }, credentials: "same-origin" }),
      ),
    );
  } catch (error) {
    console.warn("Modo sem internet indisponível neste browser", error);
  }
}
